{
  "pains": [
    {
      "id": "pain:wiki-nobody-trusts",
      "statement": "Half the pages in our Notion wiki are out of date, so nobody trusts any of them and people just write an N+1th version instead of fixing the old one.",
      "element": "b2b:ease_of_doing_business:information",
      "shape": {
        "surface": "The wiki search turns up an FAQ or a guide that is obviously wrong, next to two duplicates of it.",
        "operational": "People stop reading the wiki, ask in chat instead, and write a fresh page rather than update one they are not sure they are allowed to touch; the eng lead eventually runs a refactoring project to clean it up.",
        "personal": null,
        "personal_note": "Neither source shows what the stale wiki costs the person who owns it; the CTO's post stops at the team's distrust ('a bad smell'). Looked in the same post and the HN thread."
      },
      "workflow": "The company wiki in Notion after a Confluence-to-Notion migration, at the step where an engineer opens an imported FAQ or deployment page, finds it contradicts the Git-managed docs, and asks in Slack instead.",
      "type": "felt",
      "confidence": "medium",
      "priority": 1,
      "felt_evidence": {
        "kind": "building",
        "what": "A CTO ran an internal project to refactor the company's Notion docs a year after migrating from Confluence, because stale and duplicated pages were eroding trust.",
        "cites": ["src:4"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "A wiki migration (Confluence to Notion) carries the stale pages across and they surface a year later.",
          "cites": ["src:4"]
        },
        {
          "event": "Rolling out Notion AI over the workspace: wrong pages now come back as confident AI answers, so cleanup becomes urgent.",
          "cites": ["src:4"]
        }
      ],
      "who_feels": ["economic_buyer", "end_user"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Duplication and stale content is worse than nothing",
              "cites": ["src:4"]
            }
          ],
          "costs_them": "A docs cleanup project they have to staff, after already paying for a migration.",
          "fears": "No source states the fear directly; the quote stops at stale content being worse than having nothing.",
          "dream_outcome": "One current page per topic that the team and Notion AI can both rely on."
        },
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Even worse than no documentation is often wrong and outdated documentation.",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "Time spent following a wrong page before finding out it is wrong.",
          "fears": "No source shows the fear; the quote stops at wrong docs being worse than none.",
          "dream_outcome": "Docs that are right when they open them, so they stop double-checking in chat."
        }
      },
      "relief": {
        "line": "One page, the right one. Whoever opens it can act on it without asking in Slack.",
        "says": [],
        "gap": "Review sites (Capterra, TrustRadius) refused the fetch and Reddit could not be fetched; HN search turned up complaints about stale wikis but no one describing the after-state."
      },
      "euphoria": {
        "line": "The docs person. The team treats the wiki as the source of truth and credits whoever made it that way.",
        "says": [],
        "gap": "No buyer-voice after-state found on HN; the 4 and 5 star review pages that would carry it were blocked."
      },
      "segments": ["seg:enterprise", "seg:startup"],
      "feature_ref": "feat:kb",
      "feature_note": "The knowledge base hosts the pages but does not by itself keep them current; page verification and Notion AI answers are the parts that would need to address staleness, and the CTO source optimises docs for Notion AI results.",
      "cites": ["src:4", "src:5"]
    },
    {
      "id": "pain:too-slow-to-open",
      "statement": "Notion is so slow to open that I skip writing the thought down, and the team ends up back in Google Docs.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "The app or web page lags on open, databases load slowly, and the laptop's RAM fills up.",
        "operational": "People jot quick notes elsewhere or not at all, and teams move the wiki back to Google Workspace or cancel the paid plan.",
        "personal": "Knowing the app will feel tedious, the person reconsiders whether an idea is worth writing down, and loses some of them."
      },
      "workflow": "Opening the Notion desktop or web app to capture a quick note or file a page into the team wiki, at the moment the app is still loading.",
      "type": "felt",
      "confidence": "high",
      "priority": 2,
      "felt_evidence": {
        "kind": "switching",
        "what": "A team that had used Notion as its wiki since about 2018 switched back to Google Workspace over the slowness, and a long-time paying user cancelled over performance.",
        "cites": ["src:1", "src:2"]
      },
      "revealed_by": null,
      "triggers": [],
